select date_format('1970-01-01 08:00:00' + interval floor(`c`.`last_seen`) second,'%Y/%m/%d %H:%i') AS `时间`,coalesce(nullif(`c`.`source_ip`,''),'未识别') AS `源 IP`,case when `c`.`source_ip` is null or `c`.`source_ip` = '' then '未识别' else coalesce(nullif((select `g`.`location` from `region-a`.`ip_geo` `g` where `g`.`source_ip` = `c`.`source_ip` limit 1),''),'未查询') end AS `IP归属地`,case when `c`.`source_peer` = '172.30.3.3' and (`c`.`node` is null or `c`.`node` = '') then '172.30.3.3（云厂入口：203.0.113.103）' when `c`.`node` is null or `c`.`node` = '' then '未识别' when `r`.`node` is null then concat('未核验（',`c`.`node`,'）') when `r`.`tunnel_ip` is null then concat('直连（',`c`.`node`,'；未经过隧道）') else concat(`r`.`tunnel_ip`,'（',`c`.`node`,'）') end AS `隧道内网 IP（入口机器）`,`c`.`site` AS `目标网站` from (`region-a`.`connection_state` `c` FORCE INDEX (`by_detail`) left join `region-a`.`entry_routes` `r` on(`r`.`node` = `c`.`node` and `r`.`inbound_port` = `c`.`inbound_port`)) where `c`.`last_seen` >= unix_timestamp() - 172800 and (`c`.`source_ip` is null or `c`.`source_ip` = '' or `c`.`site` is null or `c`.`site` = '' or lcase(`c`.`site`) = 'unknown' or `c`.`node` is null or `c`.`node` = '' or `c`.`inbound_port` is null or !exists(select 1 from `region-a`.`connection_state` `d` FORCE INDEX (`by_detail`) where `d`.`last_seen` >= `c`.`last_seen` - 5 and `d`.`last_seen` <= `c`.`last_seen` + 5 and `d`.`last_seen` >= unix_timestamp() - 172800 and `d`.`source_ip` = `c`.`source_ip` and `d`.`site` = `c`.`site` and `d`.`node` = `c`.`node` and `d`.`inbound_port` = `c`.`inbound_port` and floor((`d`.`last_seen` + 2.5) / 5) = floor((`c`.`last_seen` + 2.5) / 5) and (`d`.`last_seen` > `c`.`last_seen` or `d`.`last_seen` = `c`.`last_seen` and `d`.`connection_id` < `c`.`connection_id`) limit 1))